{"code": "import importlib, sys, traceback, json, os, types, inspect, pkgutil, builtins, math, time
try:
    import nanosurf
    spm = nanosurf.SPM()
    app = spm.application
    # collect some info
    info = {
        'has_Scan': hasattr(app, 'Scan'),
        'has_OperatingMode': hasattr(app, 'OperatingMode'),
        'has_ZController': hasattr(app, 'ZController'),
    }
    # list attributes of Scan if exists
    scan_attrs = []
    if hasattr(app, 'Scan'):
        scan_attrs = [a for a in dir(app.Scan) if not a.startswith('_')]
    # list methods of application
    app_methods = [m for m in dir(app) if callable(getattr(app, m)) and not m.startswith('_')]
    result = {'info': info, 'scan_attrs': scan_attrs[:20], 'app_methods': app_methods[:20]}
    print(json.dumps(result))
except Exception as e:
    print('Error:', e)
    traceback.print_exc()
"}

